//
// Host interface of the dense fp16 prefill GEMM
// (rdna_hint_flex_dense_gemm_rdna2.cu) shared with the rdna_hint_flex composite
// op: C[M, N] = A[M, K] W[N, K]^T with fp16 operands and result and fp32
// accumulation (v_dot2_f32_f16), the layout of F.linear. The kernel designs
// live in the .cu, the dispatch table (generated by
// tools/rdna/rdna_hint_flex/gemm_sweep/gen_dispatch.py) in
// rdna_hint_flex_dense_gemm_table.cuh.
#pragma once

#include <cstdint>

#include <hip/hip_runtime.h>

namespace vllm {
namespace rdna_hint_flex {
namespace gemm {

// Design ids (kDesigns in the .cu holds their names).
constexpr int kRocblas = -1;  // not a design: leave the GEMM to rocBLAS

// The design the dispatch table picks for (M, N, K), or kRocblas when the
// shape is outside the validated set or rocBLAS measured faster. M is free
// (any tail), N and K select the table row.
int pick(int64_t M, int64_t N, int64_t K);

// Launch `design` on the current device (gfx1030 only). False, with nothing
// launched, when the design cannot run this problem: other architecture, K not
// a multiple of the design's K step, a pointer or row stride off 16 bytes, or
// an operand beyond the 32-bit byte offsets the kernel uses. M == 0 is a no-op.
bool launch(int design, const void* A, const void* W, void* C, int64_t M,
            int64_t N, int64_t K, int64_t lda, int64_t ldw, int64_t ldc,
            hipStream_t stream);

}  // namespace gemm
}  // namespace rdna_hint_flex
}  // namespace vllm
